// Rebuild every planning-engine bundle in web/js/vendor/ from ~/moneyguide/src, and write web/js/vendor/engine.json:
// a fingerprint of exactly the engine source files the bundles were built from. Every brain and every precomputed
// number records the fingerprint it was labeled with, so a stale one is caught (train/provenance.mjs, and a banner
// in the browser) instead of quietly disagreeing with the engine.
//   node train/vendor/build.mjs           rebuild the bundles and engine.json
//   node train/vendor/build.mjs --check   only recompute the fingerprint and compare it with engine.json
import fs from 'fs';
import os from 'os';
import path from 'path';
import crypto from 'crypto';
import { execSync } from 'child_process';
import { createRequire } from 'module';

const HERE = path.dirname(new URL(import.meta.url).pathname);
const ROOT = path.resolve(HERE, '../..');
const MG = process.env.MONEYGUIDE || path.join(os.homedir(), 'moneyguide');
const OUT = path.join(ROOT, 'web/js/vendor');
const MANIFEST = path.join(OUT, 'engine.json');

const src = (f) => path.join(MG, 'src', f);
const BUNDLES = [
  {
    file: 'planner.js', minify: true,
    what: 'engine + analysis + insights: the Household, Book and Firm X-ray run on this',
    entry: `export { simulate, probability, people, fullRetirementAge, START_YEAR } from ${JSON.stringify(src('engine/sim'))};
export { normalizePlan, sampleHouseholds, PORTFOLIOS } from ${JSON.stringify(src('data'))};
export { STRESS_TESTS, sensitivity, suggestScenario, describeChanges, maxSpending, ssStrategies, rothStrategies, insuranceGaps, clone } from ${JSON.stringify(src('engine/analysis'))};
export { buildInsights, applyAction } from ${JSON.stringify(src('engine/insights'))};
export { HISTORY } from ${JSON.stringify(src('engine/history'))};
export { historicalReturn, MODEL_PORTFOLIOS, PORTFOLIO_STATS } from ${JSON.stringify(src('engine/cma'))};
export { IRMAA, irmaaTier } from ${JSON.stringify(src('engine/tax'))};`,
  },
  {
    file: 'moneyguide.js', minify: true,
    what: 'engine/sim.ts + data.ts: the Engine Brain (lab tab 06) is labeled by and checked against this',
    entry: `export { simulate, probability } from ${JSON.stringify(src('engine/sim'))};
export { normalizePlan, sampleHouseholds } from ${JSON.stringify(src('data'))};`,
  },
  {
    file: 'taxlaw.js', minify: false,
    what: 'engine/tax.ts + law.ts: 2026 and 2025 federal law (IRS Rev. Proc. 2025-32, P.L. 119-21), for the Tax Brain, the compiler and the Roth Lab',
    entry: `export * from ${JSON.stringify(src('engine/law'))};
export * from ${JSON.stringify(src('engine/tax'))};`,
  },
  {
    // Its own fingerprint (engine.json "scenario"), so adding it never marks the trained brains out of date.
    file: 'scenario.js', minify: true, separate: true,
    what: 'plain/check.ts: the engine\'s plain-English front door (Roth, Social Security timing, IRMAA, RMDs, QCDs), for Meeting prep',
    entry: `export { planCheck } from ${JSON.stringify(src('plain/check'))};
export { looksSensitive, REJECTED } from ${JSON.stringify(src('plain/guard'))};`,
  },
];

const require = createRequire(path.join(MG, 'package.json'));
const esbuild = require('esbuild');

async function bundle(b, write) {
  const r = await esbuild.build({
    stdin: { contents: b.entry, resolveDir: MG, sourcefile: 'entry.ts', loader: 'ts' },
    absWorkingDir: MG, bundle: true, format: 'esm', target: 'es2020', minify: b.minify, metafile: true, write: false, logLevel: 'warning',
    banner: { js: `// Bundled from ~/moneyguide/src (${b.what}). Generated by train/vendor/build.mjs; do not edit.` },
    outfile: path.join(OUT, b.file),
  });
  if (write) fs.writeFileSync(path.join(OUT, b.file), r.outputFiles[0].text);
  return Object.keys(r.metafile.inputs).filter((f) => !f.startsWith('<stdin>') && !f.endsWith('entry.ts'));
}

/** sha256 over every source file any bundle includes, by path relative to ~/moneyguide. */
function fingerprint(inputs) {
  const h = crypto.createHash('sha256');
  for (const f of [...new Set(inputs)].sort()) h.update(f + '\0' + fs.readFileSync(path.resolve(MG, f)) + '\0');
  return h.digest('hex').slice(0, 16);
}

const check = process.argv.includes('--check');
const inputs = {};
for (const b of BUNDLES) inputs[b.file] = await bundle(b, !check);
const main = BUNDLES.filter((b) => !b.separate), extra = BUNDLES.filter((b) => b.separate);
const fp = fingerprint(main.flatMap((b) => inputs[b.file]));
const sfp = fingerprint(extra.flatMap((b) => inputs[b.file]));

if (check) {
  const m = JSON.parse(fs.readFileSync(MANIFEST, 'utf8'));
  if (m.fingerprint !== fp) {
    console.log(`engine source changed: bundles were built from ${m.fingerprint}, ~/moneyguide/src is now ${fp}. Run node train/vendor/build.mjs, then retrain.`);
    process.exit(1);
  }
  if (m.scenario && m.scenario.fingerprint !== sfp) {
    console.log(`plan_check source changed: scenario.js was built from ${m.scenario.fingerprint}, ~/moneyguide/src is now ${sfp}. Run node train/vendor/build.mjs.`);
    process.exit(1);
  }
  console.log(`bundles match ~/moneyguide/src (${fp}${m.scenario ? `, plan_check ${sfp}` : ''})`);
} else {
  let commit = null, dirty = null;
  try {
    commit = execSync('git rev-parse --short HEAD', { cwd: MG }).toString().trim();
    dirty = execSync('git status --porcelain -- src', { cwd: MG }).toString().trim() !== '';
  } catch {}
  const files = [...new Set(main.flatMap((b) => inputs[b.file]))].sort();
  const scenario = { fingerprint: sfp, files: [...new Set(extra.flatMap((b) => inputs[b.file]))].sort() };
  fs.writeFileSync(MANIFEST, JSON.stringify({ fingerprint: fp, commit, dirty, builtAt: new Date().toISOString().slice(0, 10), bundles: Object.fromEntries(BUNDLES.map((b) => [b.file, b.what])), files, scenario }, null, 2) + '\n');
  console.log(`built ${BUNDLES.map((b) => b.file).join(', ')} from ${files.length} files → engine ${fp}${commit ? ` (moneyguide ${commit}${dirty ? ', uncommitted changes' : ''})` : ''}`);
}
